21	// secretPattern matches high-entropy strings that may be secrets.
22	// Note: / is excluded to prevent matching entire file paths as single tokens.
23	// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
24	var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
25	
26	// credentialedURIPattern matches URLs that embed userinfo with a password, such
27	// as REDACTED or REDACTED These often have
28	// moderate entropy and are not reliably covered by vendor-specific scanners.
29	var credentialedURIPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9+.-]{1,31}://[^\s/?#@"'` + "`" + `<>:]*:[^\s/?#@"'` + "`" + `<>]+@[^\s"'` + "`" + `<>]+`)
30	
31	// dbPasswordKeyShape matches a DB-prefixed credential key (vendor prefix +
32	// optional `_word`/`-word` segments + `password`/`passwd`/`pwd`). Used to
33	// compose both the env-var assignment regex and the JSON-key regex so the
34	// vendor list stays in one place.
35	const dbPasswordKeyShape = `(?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)(?:[_-]+[a-z0-9]+)*[_-]*(?:password|passwd|pwd)` //nolint:gosec // regex literal, not a credential
36	
37	var (
38		jdbcPattern          = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
39		databaseURLPattern   = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
40		keywordDSNPattern    = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
41		semicolonConnPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)){2,}`)
42		// credentialValuePattern requires the prefix to start at a non-alphanumeric
43		// boundary, so APP_DB_PASSWORD matches via the leading `_` but mydbpassword
44		// does not.
45		credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])(` + dbPasswordKeyShape + `)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
46	
47		keywordHostPattern      = regexp.MustCompile(`(?i)(?:^|\s)host=`)
48		keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
49		semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
50		semicolonUserPattern    = regexp.MustCompile(`(?i)(?:^|;)\s*(?:user id|userid|user|uid)\s*=`)
51		passwordAssignmentRegex = regexp.MustCompile(`(?i)(?:^|[?&;\s])(?:password|pwd)=("[^"]*"|'[^']*'|[^&;\s"']+)`)
52		// credentialJSONKeyRegex operates on output of normalizeCredentialJSONKey
53		// (already lowercased, `-`/` `/`.` → `_`), so the `(?i)` flag is unnecessary.
54		credentialJSONKeyRegex  = regexp.MustCompile(`^` + dbPasswordKeyShape + `$`)
55		genericPasswordKeyRegex = regexp.MustCompile(`(?i)^(?:password|passwd|pwd)$`)
56	)
