58	// entropyThreshold is the minimum Shannon entropy for a string to be considered
59	// a secret. 4.5 was chosen through trial and error: high enough to avoid false
60	// positives on common words and identifiers, low enough to catch typical API keys
61	// and tokens which tend to have entropy well above 5.0.
62	const entropyThreshold = 4.5
63	
64	// RedactedPlaceholder is the replacement text used for redacted secrets.
65	const RedactedPlaceholder = "REDACTED"
66	
67	// placeholderSecretValues lists lowercase values that should be treated as
68	// non-secrets when they appear as a credential value: prior redactions
69	// (REDACTED / [REDACTED] / <REDACTED>), common documentation placeholders,
70	// and obviously-non-real defaults. Values matched by shape (mask runs,
71	// `<…>` brackets, `${…}` shell expansion) are handled separately.
72	var placeholderSecretValues = func() map[string]struct{} {
73		lower := strings.ToLower(RedactedPlaceholder)
74		values := []string{
75			lower, "[" + lower + "]", "<" + lower + ">",
76			"changeme", "example", "placeholder",
77			"your_password", "your_db_password", "your_secret",
78			"secret_here",
79		}
80		out := make(map[string]struct{}, len(values))
81		for _, v := range values {
82			out[v] = struct{}{}
83		}
84		return out
85	}()
