87	// RedactedBytes represents transcript data that has been through secret
88	// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
89	// checkpoint stores) accept this type to enforce the contract at compile time.
90	//
91	// Produced by JSONLBytes (primary constructor) or trusted wrappers for data
92	// previously persisted by checkpoint writers.
93	type RedactedBytes struct {
94		data []byte
95	}
96	
97	// Bytes returns the underlying byte slice.
98	func (r RedactedBytes) Bytes() []byte {
99		return r.data
100	}
101	
102	// Len returns the number of bytes in the redacted payload.
103	func (r RedactedBytes) Len() int {
104		return len(r.data)
105	}
106	
107	// AlreadyRedacted wraps transcript bytes known to already be redacted by a
108	// prior write path. Use this ONLY for trusted sources such as persisted
109	// checkpoint transcripts or controlled test fixtures. For fresh transcript
110	// input, use JSONLBytes.
111	func AlreadyRedacted(data []byte) RedactedBytes {
112		return RedactedBytes{data: data}
113	}
