131	// region represents a byte range to redact.
132	type region struct{ start, end int }
133	
134	// taggedRegion extends region with a label for typed replacement tokens.
135	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
136	type taggedRegion struct {
137		region
138	
139		label string
140	}
