148	type connectionStringRule struct {
149		pattern   *regexp.Regexp
150		hasSecret func(string) bool
151	}
152	
153	var connectionStringRules = []connectionStringRule{
154		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
155		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
156		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
157		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
158	}
