160	// String replaces secrets and PII in s using layered detection:
161	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
162	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
163	// 3. Credentialed URIs: URLs containing userinfo passwords
164	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
165	// 5. User-defined custom rules: configured via ConfigureCustomRules
166	// 6. Bounded credential key/value pairs: DB_PASSWORD=...
167	// 7. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
168	// A string is redacted if ANY method flags it.
169	func String(s string) string {
170		return applyRegions(s, detectAllLayers(s))
171	}
172	
173	// detectAllLayers runs the seven always-on/opt-in regex-based redaction
174	// layers and returns their tagged regions. The OpenAI Privacy Filter
175	// (layer 8) is NOT included — callers that want it append detectOPF spans
176	// to the result before passing to applyRegions. See StringWithPrivacyFilter
177	// for the augmented flow.
178	func detectAllLayers(s string) []taggedRegion {
179		var regions []taggedRegion
180	
181		// 1. Entropy-based detection (secrets — always on).
182		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
183			start, end := loc[0], loc[1]
184	
185			// Don't consume characters that are part of JSON/string escape sequences.
186			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
187			// (consuming the 'n' from '\n'), and after replacement the '\' would be
188			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
189			// Only skip for known JSON escape letters to avoid trimming real secrets
190			// that happen to follow a literal backslash in decoded content.
191			if start > 0 && s[start-1] == '\\' {
192				switch s[start] {
193				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
194					start++
195					if end-start < 10 {
196						continue
197					}
198				}
199			}
200	
201			if shannonEntropy(s[start:end]) > entropyThreshold {
202				regions = append(regions, taggedRegion{region: region{start, end}})
203			}
204		}
205	
206		// 2. Pattern-based detection via betterleaks (secrets — always on).
207		if d := getDetector(); d != nil {
208			for _, f := range d.DetectString(s) {
209				if f.Secret == "" {
210					continue
211				}
212				searchFrom := 0
213				for {
214					idx := strings.Index(s[searchFrom:], f.Secret)
215					if idx < 0 {
216						break
217					}
218					absIdx := searchFrom + idx
219					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
220					searchFrom = absIdx + len(f.Secret)
221				}
222			}
223		}
224	
225		// 3. Credentialed URIs (secrets — always on).
226		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
227			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
228		}
229	
230		// 4. Database and connection-string detection (secrets — always on).
231		regions = append(regions, detectConnectionStrings(s)...)
232	
233		// 5. User-defined custom rules (secrets — only runs when configured).
234		regions = append(regions, detectCustomRules(getCustomRulesConfig(), s)...)
235	
236		// 6. Bounded credential key/value detection (secrets — always on).
237		regions = append(regions, detectCredentialValues(s)...)
238	
239		// 7. PII detection (opt-in — only runs when configured).
240		regions = append(regions, detectPII(getPIIConfig(), s)...)
241	
242		return regions
243	}
