245	// applyRegions sorts, merges, and replaces the given regions in s, returning
246	// the redacted string. Returns s unchanged when regions is empty.
247	func applyRegions(s string, regions []taggedRegion) string {
248		if len(regions) == 0 {
249			return s
250		}
251	
252		sort.Slice(regions, func(i, j int) bool {
253			if regions[i].start != regions[j].start {
254				return regions[i].start < regions[j].start
255			}
256			if regions[i].end != regions[j].end {
257				return regions[i].end > regions[j].end // larger region first
258			}
259			return regions[i].label < regions[j].label // deterministic tie-break
260		})
261		merged := []taggedRegion{regions[0]}
262		for _, r := range regions[1:] {
263			last := &merged[len(merged)-1]
264			if r.start <= last.end {
265				if r.end > last.end {
266					last.end = r.end
267				}
268				// Keep the existing label (first/larger region wins)
269			} else {
270				merged = append(merged, r)
271			}
272		}
273	
274		var b strings.Builder
275		prev := 0
276		for _, r := range merged {
277			b.WriteString(s[prev:r.start])
278			b.WriteString(replacementToken(r.label))
279			prev = r.end
280		}
281		b.WriteString(s[prev:])
282		return b.String()
283	}
