285	func detectConnectionStrings(s string) []taggedRegion {
286		if !strings.ContainsRune(s, '=') {
287			return nil
288		}
289		var regions []taggedRegion
290		for _, rule := range connectionStringRules {
291			regions = append(regions, detectConnectionStringRule(s, rule)...)
292		}
293		return regions
294	}
295	
296	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
297		var regions []taggedRegion
298		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
299			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
300			if start >= end {
301				continue
302			}
303			if rule.hasSecret(s[start:end]) {
304				regions = append(regions, taggedRegion{region: region{start, end}})
305			}
306		}
307		return regions
308	}
309	
310	func trimConnectionStringEnd(s string, start, end int) int {
311		for end > start {
312			switch s[end-1] {
313			case '.', ',', ';', ':', '!', '?', ')', ']':
314				end--
315			default:
316				return end
317			}
318		}
319		return end
320	}
321	
322	func hasJDBCPassword(candidate string) bool {
323		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
324			return false
325		}
326		return hasNonPlaceholderPasswordAssignment(candidate)
327	}
328	
329	func hasDatabaseURLSecret(candidate string) bool {
330		u, err := url.Parse(candidate)
331		if err != nil || u.Scheme == "" || u.Host == "" {
332			return false
333		}
334		for key, values := range u.Query() {
335			if !isPasswordQueryKey(key) {
336				continue
337			}
338			for _, value := range values {
339				if hasNonPlaceholderPasswordValue(value) {
340					return true
341				}
342			}
343		}
344		return false
345	}
346	
347	func isPasswordQueryKey(key string) bool {
348		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
349	}
350	
351	func hasKeywordDSNPassword(candidate string) bool {
352		return keywordHostPattern.MatchString(candidate) &&
353			keywordUserPattern.MatchString(candidate) &&
354			hasNonPlaceholderPasswordAssignment(candidate)
355	}
356	
357	func hasSemicolonConnectionPassword(candidate string) bool {
358		return semicolonServerPattern.MatchString(candidate) &&
359			semicolonUserPattern.MatchString(candidate) &&
360			hasNonPlaceholderPasswordAssignment(candidate)
361	}
362	
363	func detectCredentialValues(s string) []taggedRegion {
364		var regions []taggedRegion
365		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
366			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
367				continue
368			}
369			start, end := unquoteRange(s, loc[4], loc[5])
370			if hasNonPlaceholderPasswordValue(s[start:end]) {
371				regions = append(regions, taggedRegion{region: region{start, end}})
372			}
373		}
374		return regions
375	}
376	
377	func unquoteRange(s string, start, end int) (int, int) {
378		if end-start < 2 {
379			return start, end
380		}
381		first, last := s[start], s[end-1]
382		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
383			return start + 1, end - 1
384		}
385		return start, end
386	}
387	
388	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
389		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
390			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
391				start, end := unquoteRange(candidate, loc[2], loc[3])
392				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
393					return true
394				}
395			}
396		}
397		return false
398	}
399	
400	func hasNonPlaceholderPasswordValue(value string) bool {
401		return value != "" && !isPlaceholderSecretValue(value)
402	}
403	
404	func isPlaceholderSecretValue(value string) bool {
405		trimmed := strings.Trim(strings.TrimSpace(value), `"'`)
406		if trimmed == "" {
407			return true
408		}
409		if isBracketedPlaceholder(trimmed) {
410			return true
411		}
412		normalized := strings.ToLower(trimmed)
413		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
414			return true
415		}
416		if _, ok := placeholderSecretValues[normalized]; ok {
417			return true
418		}
419		return isRepeatedCharPlaceholder(normalized)
420	}
421	
422	// bracketedPlaceholderInteriorRE matches the inside of a "<…>" placeholder
423	// shape: lowercase letters joined by `-` or `_`. Digits, mixed case, and
424	// special chars are rejected so values like `<hunter2>` or `<RealPassword>`
425	// still fall through to redaction.
426	var bracketedPlaceholderInteriorRE = regexp.MustCompile(`^[a-z][a-z_-]*$`)
427	
428	// isBracketedPlaceholder reports whether s is a "<name>" doc placeholder
429	// (e.g. "<password>", "<your-db-password>"). The minimum total length of 5
430	// keeps this from firing on `<a>` / `<ab>`.
431	func isBracketedPlaceholder(s string) bool {
432		if len(s) < 5 || s[0] != '<' || s[len(s)-1] != '>' {
433			return false
434		}
435		return bracketedPlaceholderInteriorRE.MatchString(s[1 : len(s)-1])
436	}
437	
438	// isRepeatedCharPlaceholder reports whether s is a run of a single masking
439	// character commonly used to redact values in docs and screenshots, e.g.
440	// "***", "xxxx", "....", "----". The minimum length of 3 keeps single-char
441	// or 2-char values like `x` or `**` from being treated as masks.
442	func isRepeatedCharPlaceholder(s string) bool {
443		if len(s) < 3 {
444			return false
445		}
446		first := s[0]
447		switch first {
448		case '*', 'x', '.', '-':
449		default:
450			return false
451		}
452		for i := 1; i < len(s); i++ {
453			if s[i] != first {
454				return false
455			}
456		}
457		return true
458	}
459	
460	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
461		normalized := normalizeCredentialJSONKey(key)
462		if credentialJSONKeyRegex.MatchString(normalized) {
463			return true
464		}
465		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
466	}
467	
468	func isCredentialJSONObject(obj map[string]any) bool {
469		var hasHost, hasUser bool
470		for key := range obj {
471			switch normalizeCredentialJSONKey(key) {
472			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
473				hasHost = true
474			case "user", "username", "userid", "user_id", "uid":
475				hasUser = true
476			}
477			if hasHost && hasUser {
478				return true
479			}
480		}
481		return false
482	}
483	
484	func normalizeCredentialJSONKey(key string) string {
485		key = strings.ToLower(strings.TrimSpace(key))
486		key = strings.ReplaceAll(key, "-", "_")
487		key = strings.ReplaceAll(key, " ", "_")
488		// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
489		// like "db.password" or "mysql.root.password"; treat them like underscored.
490		key = strings.ReplaceAll(key, ".", "_")
491		return key
492	}
