504	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
505	// the result as RedactedBytes, certifying the output has been through redaction.
506	func JSONLBytes(b []byte) (RedactedBytes, error) {
507		s := string(b)
508		redacted, err := JSONLContent(s)
509		if err != nil {
510			return RedactedBytes{}, err
511		}
512		if redacted == s {
513			return RedactedBytes{data: b}, nil
514		}
515		return RedactedBytes{data: []byte(redacted)}, nil
516	}
