518	// JSONLBytesWithPrivacyFilter augments JSONLBytes with the OpenAI Privacy
519	// Filter. Use only at condensation/export boundaries; per-turn writes must
520	// use JSONLBytes.
521	func JSONLBytesWithPrivacyFilter(ctx context.Context, b []byte) (RedactedBytes, error) {
522		s := string(b)
523		redacted, err := JSONLContentWithPrivacyFilter(ctx, s)
524		if err != nil {
525			return RedactedBytes{}, err
526		}
527		if redacted == s {
528			return RedactedBytes{data: b}, nil
529		}
530		return RedactedBytes{data: []byte(redacted)}, nil
531	}
532	
533	// BytesWithPrivacyFilter augments Bytes with the OpenAI Privacy Filter for
534	// raw (non-JSONL) byte content. Used by checkpoint write paths that handle
535	// metadata files which may or may not be JSONL.
536	func BytesWithPrivacyFilter(ctx context.Context, b []byte) []byte {
537		s := string(b)
538		redacted := StringWithPrivacyFilter(ctx, s)
539		if redacted == s {
540			return b
541		}
542		return []byte(redacted)
543	}
544	
545	// JSONLContent parses each line as JSON to determine which string values
546	// need redaction, then performs targeted replacements on the raw JSON bytes.
547	// Lines with no secrets are returned unchanged, preserving original formatting.
548	//
549	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
550	// OpenCode export), the function first attempts to parse the entire content as
551	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
552	// is used instead of falling back to entropy-based detection on raw text lines,
553	// which would corrupt high-entropy identifiers.
554	func JSONLContent(content string) (string, error) {
555		return jsonlContentImpl(content, String)
556	}
557	
558	// jsonlContentImpl is the body of JSONLContent parameterized by a per-leaf
559	// redactor. JSONLContent passes String (regex layers only). The OPF-enabled
560	// flow uses two passes: one with a collector that records leaves and returns
561	// identity, one with a redactor that combines regex layers with cached OPF
562	// spans for the recorded leaves.
563	func jsonlContentImpl(content string, redactor func(string) string) (string, error) {
564		// Try parsing the entire content as a single JSON value first.
565		// Uses a streaming decoder to avoid copying the full content into []byte.
566		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
567		// the content is JSONL (multiple values) and we fall through to line-by-line.
568		trimmed := strings.TrimSpace(content)
569		if len(trimmed) > 0 {
570			dec := json.NewDecoder(strings.NewReader(trimmed))
571			var parsed any
572			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
573				// Content is a single JSON value (object/array) — redact field-aware.
574				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
575				if err != nil {
576					return "", err
577				}
578				return result, nil
579			}
580		}
581	
582		// Fall back to line-by-line JSONL processing.
583		lines := strings.Split(content, "\n")
584		var b strings.Builder
585		for i, line := range lines {
586			if i > 0 {
587				b.WriteByte('\n')
588			}
589			lineTrimmed := strings.TrimSpace(line)
590			if lineTrimmed == "" {
591				b.WriteString(line)
592				continue
593			}
594			var parsed any
595			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
596				b.WriteString(redactor(line))
597				continue
598			}
599			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
600			if err != nil {
601				return "", err
602			}
603			b.WriteString(result)
604		}
605		return b.String(), nil
606	}
