608	// StringWithPrivacyFilter augments String with the OpenAI Privacy Filter.
609	// Use only at condensation/export boundaries; per-turn writes must use
610	// String to avoid the OPF shell-out cost inside the agent loop.
611	func StringWithPrivacyFilter(ctx context.Context, s string) string {
612		regions := detectAllLayers(s)
613		regions = append(regions, detectOPF(ctx, getOPFConfig(), s)...)
614		return applyRegions(s, regions)
615	}
