617	// JSONLContentWithPrivacyFilter augments JSONLContent with the OpenAI
618	// Privacy Filter via batched inference. Walks the content twice: pass 1
619	// collects unique prose-shaped leaves into a single RedactBatch call;
620	// pass 2 applies the seven regex layers per leaf plus the cached OPF spans
621	// for that leaf. One OPF shell-out covers the whole transcript instead of
622	// one per leaf — without batching, a typical 500-leaf transcript would
623	// take many minutes per commit.
624	//
625	// Falls back to the plain JSONLContent flow when OPF is unconfigured, the
626	// breaker is tripped, no categories are enabled, or the batch call errors.
627	func JSONLContentWithPrivacyFilter(ctx context.Context, content string) (string, error) {
628		cfg := getOPFConfig()
629		if cfg == nil || !cfg.Enabled || cfg.runtime == nil || opfBreakerTripped.Load() {
630			return jsonlContentImpl(content, String)
631		}
632		cats := enabledCategories(cfg)
633		if len(cats) == 0 {
634			return jsonlContentImpl(content, String)
635		}
636	
637		// Pass 1: collect eligible (has-space, deduped) leaves. The collector
638		// closure returns identity so the JSONL walker doesn't mutate content.
639		seen := make(map[string]struct{})
640		var inputs []string
641		if _, err := jsonlContentImpl(content, func(v string) string {
642			if strings.ContainsRune(v, ' ') {
643				if _, ok := seen[v]; !ok {
644					seen[v] = struct{}{}
645					inputs = append(inputs, v)
646				}
647			}
648			return v
649		}); err != nil {
650			return "", err
651		}
652	
653		// Pass 2: single batched OPF call.
654		spansByInput := make(map[string][]Span, len(inputs))
655		if len(inputs) > 0 {
656			fmt.Fprintln(opfStderr, "→ OpenAI Privacy Filter: scanning transcript…")
657			start := time.Now()
658			batched, err := cfg.runtime.RedactBatch(ctx, inputs, cats)
659			if err != nil {
660				handleOPFFailure(ctx, cfg, err)
661				return jsonlContentImpl(content, String)
662			}
663			fmt.Fprintf(opfStderr, "✓ OpenAI Privacy Filter: done (%.1fs)\n", time.Since(start).Seconds())
664			if len(batched) < len(inputs) {
665				slog.Warn("OPF runtime returned fewer span slices than inputs",
666					slog.String("component", "redaction"),
667					slog.Int("inputs", len(inputs)),
668					slog.Int("returned", len(batched)),
669				)
670			}
671			for i, in := range inputs {
672				if i >= len(batched) {
673					break
674				}
675				spansByInput[in] = batched[i]
676			}
677		}
678	
679		// Pass 3: per-leaf regex layers + cached OPF spans.
680		return jsonlContentImpl(content, func(v string) string {
681			regions := detectAllLayers(v)
682			if spans, ok := spansByInput[v]; ok {
683				for _, sp := range spans {
684					if !cfg.Categories[sp.Label] {
685						continue
686					}
687					if sp.Start < 0 || sp.End > len(v) || sp.Start >= sp.End {
688						continue
689					}
690					regions = append(regions, taggedRegion{
691						region: region{sp.Start, sp.End},
692						label:  mapOPFLabel(sp.Label),
693					})
694				}
695			}
696			return applyRegions(v, regions)
697		})
698	}
