37	func (f *fakeRuntime) RedactBatch(_ context.Context, inputs []string, _ []string) ([][]Span, error) {
38		f.mu.Lock()
39		defer f.mu.Unlock()
40		f.batchCalls++
41		if f.err != nil {
42			return nil, f.err
43		}
44		out := make([][]Span, len(inputs))
45		for i := range inputs {
46			out[i] = f.spans
47		}
48		return out, nil
49	}
