53	// Pre-compiled regexes for trailer parsing.
54	var (
55		strategyTrailerRegex     = regexp.MustCompile(StrategyTrailerKey + `:\s*(.+)`)
56		metadataTrailerRegex     = regexp.MustCompile(MetadataTrailerKey + `:\s*(.+)`)
57		taskMetadataTrailerRegex = regexp.MustCompile(MetadataTaskTrailerKey + `:\s*(.+)`)
58		baseCommitTrailerRegex   = regexp.MustCompile(BaseCommitTrailerKey + `:\s*([a-f0-9]{40})`)
59		condensationTrailerRegex = regexp.MustCompile(CondensationTrailerKey + `:\s*(.+)`)
60		sessionTrailerRegex      = regexp.MustCompile(SessionTrailerKey + `:\s*(.+)`)
61		checkpointTrailerRegex   = regexp.MustCompile(CheckpointTrailerKey + `:\s*(` + checkpointID.Pattern + `)(?:\s|$)`)
62	)
