126	// ParseCheckpoint extracts the checkpoint ID from a commit message.
127	// Returns the CheckpointID and true if found, empty ID and false otherwise.
128	func ParseCheckpoint(commitMessage string) (checkpointID.CheckpointID, bool) {
129		matches := checkpointTrailerRegex.FindStringSubmatch(commitMessage)
130		if len(matches) > 1 {
131			idStr := strings.TrimSpace(matches[1])
132			// Validate it's a proper checkpoint ID
133			if cpID, err := checkpointID.NewCheckpointID(idStr); err == nil {
134				return cpID, true
135			}
136		}
137		return checkpointID.EmptyCheckpointID, false
138	}
