140	// ParseAllCheckpoints extracts all checkpoint IDs from a commit message.
141	// Returns a slice of CheckpointIDs (may be empty if none found).
142	// Duplicate IDs are deduplicated while preserving order.
143	// This is useful for squash merge commits that contain multiple Entire-Checkpoint trailers.
144	func ParseAllCheckpoints(commitMessage string) []checkpointID.CheckpointID {
145		matches := checkpointTrailerRegex.FindAllStringSubmatch(commitMessage, -1)
146		if len(matches) == 0 {
147			return nil
148		}
149	
150		seen := make(map[string]bool)
151		ids := make([]checkpointID.CheckpointID, 0, len(matches))
152		for _, match := range matches {
153			if len(match) > 1 {
154				idStr := strings.TrimSpace(match[1])
155				if !seen[idStr] {
156					if cpID, err := checkpointID.NewCheckpointID(idStr); err == nil {
157						seen[idStr] = true
158						ids = append(ids, cpID)
159					}
160				}
161			}
162		}
163		return ids
164	}
165	
166	// ParseAllSessions extracts all session IDs from a commit message.
167	// Returns a slice of session IDs (may be empty if none found).
168	// Duplicate session IDs are deduplicated while preserving order.
169	// This is useful for commits that may have multiple Entire-Session trailers.
170	func ParseAllSessions(commitMessage string) []string {
171		matches := sessionTrailerRegex.FindAllStringSubmatch(commitMessage, -1)
172		if len(matches) == 0 {
173			return nil
174		}
175	
176		seen := make(map[string]bool)
177		sessionIDs := make([]string, 0, len(matches))
178		for _, match := range matches {
179			if len(match) > 1 {
180				sessionID := strings.TrimSpace(match[1])
181				if !seen[sessionID] {
182					seen[sessionID] = true
183					sessionIDs = append(sessionIDs, sessionID)
184				}
185			}
186		}
187		return sessionIDs
188	}
