263	// appendTrailerLine appends a single pre-formatted trailer line (e.g. "Key: value")
264	// to message in trailer-block-aware format. If the message already ends with a
265	// trailer paragraph the line is joined directly to it; otherwise a blank line is
266	// inserted first to start a new trailer block.
267	func appendTrailerLine(message, trailerLine string) string {
268		trimmed := strings.TrimRight(message, "\n")
269	
270		lines := strings.Split(trimmed, "\n")
271		i := len(lines) - 1
272		for i >= 0 && strings.HasPrefix(strings.TrimSpace(lines[i]), "#") {
273			i--
274		}
275	
276		hasTrailerBlock := false
277		if i >= 0 {
278			last := strings.TrimSpace(lines[i])
279			if last != "" && IsTrailerLine(last) {
280				for i > 0 {
281					i--
282					above := strings.TrimSpace(lines[i])
283					if strings.HasPrefix(above, "#") {
284						continue
285					}
286					if above == "" {
287						hasTrailerBlock = true
288						break
289					}
290					if !IsTrailerLine(above) {
291						break
292					}
293				}
294			}
295		}
296	
297		if hasTrailerBlock {
298			return trimmed + "\n" + trailerLine + "\n"
299		}
300		return trimmed + "\n\n" + trailerLine + "\n"
301	}
